    /// <summary>Creates the connection dialog view model using services resolved from the app container.</summary>
    public ConnectionDialogViewModel()
        : this(App.ServiceProvider.GetRequiredService<IDialogService>(), App.ServiceProvider?.GetService<IBootloaderWatcher>()) { }

    /// <summary>Creates the connection dialog view model.</summary>
    /// <param name="dialogService">Dialog service used to display modal dialogs.</param>
    /// <param name="watcher">Optional app-global bootloader watcher (null in unit tests without the DI container).</param>
    public ConnectionDialogViewModel(
        IDialogService dialogService,
        IBootloaderWatcher? watcher = null)
    {
        _dialogService = dialogService;
        _watcher = watcher;
        ConnectCommand = new AsyncRelayCommand<object>(ConnectAsync);
        ConnectSerialCommand = new AsyncRelayCommand<object>(ConnectSerialAsync);
        ConnectManualSerialCommand = new AsyncRelayCommand(ConnectManualSerialAsync);
        ConnectManualWifiCommand = new AsyncRelayCommand(ConnectManualWifiAsync);

        // The watcher holds bootloaders app-wide, so its list may already be populated before the dialog
        // opens. Reflect its current count and track changes so the "scanning…" overlay is accurate.
        // (Bootloaders is a ReadOnlyObservableCollection — its CollectionChanged is an explicit interface
        // member, so reach it via INotifyCollectionChanged.)
        if (_watcher != null)
        {
            HasNoHidDevices = _watcher.Bootloaders.Count == 0;
            ((System.Collections.Specialized.INotifyCollectionChanged)_watcher.Bootloaders).CollectionChanged
                += OnHidDevicesChanged;

            // A HID bootloader write can outlive the modal firmware dialog (closing it mid-flash only
            // cancels; the watcher's flash lease is released asynchronously afterwards). Subscribe so the
            // end of the write is a restart trigger of its own — without it, a resume refused while the
            // write was still running would never be retried (issue #777).
            _watcher.FlashInProgressChanged += OnBootloaderFlashInProgressChanged;
        }

        // Set up the duplicate device handler
        ConnectionManager.Instance.DuplicateDeviceHandler = HandleDuplicateDevice;

        // React to a firmware update starting/ending while this dialog is open: pause serial + WiFi
        // discovery for the duration so a per-cycle port probe can't steal the COM port during Core's
        // post-flash reconnect window (issue #738). The Start*Discovery guards below cover a dialog
        // opened mid-flash; this event covers a dialog already open when the flash starts.
        ConnectionManager.Instance.FirmwareUpdateInProgressChanged += OnFirmwareUpdateInProgressChanged;
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.OnFirmwareUpdateInProgressChanged
    private void OnFirmwareUpdateInProgressChanged(object? sender, EventArgs e)
    {
        // Marshal onto the UI thread: the event is raised from the firmware coordinator's async flow,
        // and the discovery start/stop paths mutate bound collections.
        _marshalToUiThread(() =>
        {
            if (_closed) { return; }

            if (ConnectionManager.Instance.IsFirmwareUpdateInProgress)
            {
                _ = StopWiFiDiscoveryAsync();
                _ = StopSerialDiscoveryAsync();
            }
            else
            {
                // Auto-update finished — bring discovery back so the dialog keeps listing devices. The
                // restart carries the IsDiscoveryPausedForFirmware guard, so it is correctly refused when
                // a concurrent HID bootloader flash still needs the bus quiet (issue #777); that flash's
                // own release path calls the restart again.
                RestartDiscoveryAfterFirmwarePause();
            }
        });
    }

    /// <summary>
    /// Reacts to a HID bootloader write starting or finishing on the app-global watcher. Only the falling
    /// edge needs work: <see cref="ConnectHid"/> already drained both transports before the write could
    /// start, and <see cref="IsDiscoveryPausedForFirmware"/> keeps them from restarting while it runs.
    /// When it ends, retry the restart — the firmware dialog may already have closed (and had its own
    /// restart refused) while the write was still unwinding (issue #777).
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.OnBootloaderFlashInProgressChanged
    private void OnBootloaderFlashInProgressChanged(object? sender, EventArgs e)
    {
        _marshalToUiThread(() =>
        {
            if (_closed || _watcher == null || _watcher.IsFlashInProgress) { return; }

            RestartDiscoveryAfterFirmwarePause();
        });
    }

    /// <summary>
    /// Brings serial + WiFi discovery back after one of the firmware pause reasons cleared. Both starts
    /// re-check <see cref="IsDiscoveryPausedForFirmware"/>, so calling this while another reason is still
    /// active is a harmless no-op — and because every reason calls this when it clears, whichever one
    /// clears last performs the actual restart. That is what stops a guard from leaving discovery paused
    /// for the rest of the dialog's life.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.RestartDiscoveryAfterFirmwarePause
    private void RestartDiscoveryAfterFirmwarePause()
    {
        // Straight calls. The hand-rolled loop needed these deferred until an in-flight stop had
        // drained, because its stop could leave the loop task running past cancellation on a wedged
        // port and Start*Discovery refused to start while that was true — so a dropped start could
        // leave discovery stopped for the rest of the dialog (issue #738). The stop paths now retire
        // the finder reference before they await Core's ordered stop, so a start issued during a drain
        // is accepted rather than refused, and the probe of the finder being torn down cannot collide
        // with the new one's: Core claims serial-port probes process-wide, so the fresh pass waits for
        // the retiring claim to clear instead of double-opening the port.
        StartWiFiDiscovery();
        StartSerialDiscovery();
    }

    /// <summary>
    /// True while some firmware operation needs this dialog's serial + WiFi discovery quiesced: a
    /// coordinator auto-update (<see cref="ConnectionManager.IsFirmwareUpdateInProgress"/>), an open HID
    /// firmware dialog, or a HID bootloader write still in flight on the app-global watcher. The last two
    /// are invisible to the connection manager — a manual flash never sets <c>DeviceBeingUpdated</c> — so
    /// gating on the connection manager alone let one device's auto-update ending re-open COM ports and
    /// resume WiFi broadcasts in the middle of another device's HID flash (issue #777).
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.IsDiscoveryPausedForFirmware
    private bool IsDiscoveryPausedForFirmware =>
        ConnectionManager.Instance.IsFirmwareUpdateInProgress
        || _hidFirmwareDialogOpen
        || _watcher?.IsFlashInProgress == true;

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.OnHidDevicesChanged
    private void OnHidDevicesChanged(object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e)
    {
        HasNoHidDevices = AvailableHidDevices.Count == 0;
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.StartConnectionFinders
    public void StartConnectionFinders()
    {
        Common.Loggers.AppLogger.Instance.AddBreadcrumb("discovery", "Device discovery started");

        StartWiFiDiscovery();
        StartSerialDiscovery();
        // HID bootloader discovery + holding is the app-global watcher's job (started at app startup),
        // not the dialog's — the dialog only binds to AvailableHidDevices.
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.StartWiFiDiscovery
    private void StartWiFiDiscovery()
    {
        // Idempotent: a non-null finder is a running scan. The stop paths await Core's ordered stop
        // before nulling it, so unlike the hand-rolled loop there is no "cancelled but still draining"
        // state for a restart to race — which is what RestartDiscoveryWhenDrained existed to retry past.
        if (_closed || _wifiFinder != null) { return; }

        // Don't run discovery during any firmware operation: its per-cycle bus probing can starve the
        // flash / steal the reconnecting COM port (issue #738) and can starve a HID bootloader's I/O
        // mid-write (issue #777). Covers a dialog opened mid-flash; the release path of whichever pause
        // reason clears last restarts discovery.
        if (IsDiscoveryPausedForFirmware) { return; }

        // Drop stale devices from the previous discovery session when the scan is torn down and
        // recreated (the dialog-open / firmware-flash resume path): the bound list otherwise outlives
        // the scan that populated it and keeps devices that are no longer answering (issue #621).
        // Routed through the UI marshal like every other AvailableWiFiDevices mutation.
        _marshalToUiThread(() =>
        {
            AvailableWiFiDevices.Clear();
            HasNoWiFiDevices = true;
            // Discovery is live again, so retire whatever the previous run gave up with (issue #290).
            WiFiDiscoveryError = null;
        });

        _wifiConsecutiveFaults = 0;

        var inner = _createWifiFinder();

        // Core's default identity for WiFi prefers MAC address, which is the same key
        // HandleWifiDeviceFound dedups AvailableWiFiDevices by — so its live set and the bound list
        // agree without an IdentitySelector.
        var finder = new ContinuousDeviceFinder(
            inner,
            new ContinuousDiscoveryOptions
            {
                Interval = _wifiScanInterval,
                PassTimeout = _wifiPassTimeout,
            });

        // Reset the fault counter on a pass that actually completed. Core reports faults but has no
        // "pass finished" signal of its own; the wrapped finder raises DiscoveryCompleted only on its
        // success path, which is exactly the "this sweep was clean" edge the old loop counted on.
        //
        // Guarded on the scan being current, like every other callback here. A stop that gave up on
        // its bounded wait leaves the retired pass in flight, and its eventual completion would
        // otherwise clear the REPLACEMENT scan's fault count and keep it from ever giving up.
        inner.DiscoveryCompleted += (_, _) =>
        {
            if (ReferenceEquals(finder, _wifiFinder)) { _wifiConsecutiveFaults = 0; }
        };

        finder.DeviceDiscovered += HandleCoreWifiDeviceDiscovered;
        finder.DeviceLost += HandleCoreWifiDeviceLost;
        finder.ScanError += HandleWifiScanError;
        _wifiFinder = finder;
        finder.Start();
    }

    /// <summary>
    /// Starts serial discovery on a fresh finder, dropping the devices the previous finder found —
    /// the teardown-and-restart paths (dialog open, resume after a firmware pause).
    /// </summary>
    /// <remarks>
    /// Matches <see cref="StartWiFiDiscovery"/>. Use
    /// <see cref="ResumeSerialDiscoveryKeepingDiscoveredDevices"/> instead on the retry-after-a-failed-connect
    /// paths, where the list is what the user is about to press Connect on again.
    /// </remarks>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.StartSerialDiscovery
    private void StartSerialDiscovery() => StartSerialFinder(clearDiscoveredDevices: true);

    /// <summary>
    /// Recreates the serial finder but keeps <see cref="AvailableSerialDevices"/> as it is.
    /// </summary>
    /// <remarks>
    /// For the paths that restart discovery immediately after a connect attempt did not take. The
    /// device that just failed is the one the user is most likely to retry, and a sweep runs every
    /// two seconds — blanking the list back to "Scanning for USB devices…" would take the retry
    /// target away from them for no gain. Upstream <c>daqifi-desktop</c> does not clear here either.
    /// </remarks>
    private void ResumeSerialDiscoveryKeepingDiscoveredDevices() =>
        StartSerialFinder(clearDiscoveredDevices: false);

    /// <summary>
    /// The shared body of the two entry points above. Deliberately NOT an overload of
    /// <c>StartSerialDiscovery</c>: the dialog's tests reach these by
    /// <c>GetMethod("StartSerialDiscovery", …)</c>, which throws on an ambiguous match.
    /// </summary>
    private void StartSerialFinder(bool clearDiscoveredDevices)
    {
        // Idempotent while running — see StartWiFiDiscovery for why a finder reference is now a
        // sufficient guard where a task reference was not.
        if (_closed || _serialFinder != null) { return; }

        // Don't probe COM ports during a firmware update: Core opens/reconnects the device's port
        // itself across the flash, and the SerialDeviceFinder opens every DAQiFi VID/PID port each
        // cycle — a probe landing in Core's JumpingToApp reconnect window steals the port and strands
        // the update in a timeout (issue #738), and the same probing can starve a HID bootloader's I/O
        // mid-write on another device (issue #777). Covers a dialog opened mid-flash; the release path
        // of whichever pause reason clears last restarts discovery.
        if (IsDiscoveryPausedForFirmware) { return; }

        // Drop what the previous scan found, for the same reason StartWiFiDiscovery does (issue
        // #621): the bound list outlives the scan that populated it, so without this it keeps
        // devices that are no longer there. The case that bites is the firmware-flash resume — the
        // flashed board re-enumerates its USB-CDC port and can come back under a different port
        // name, leaving the pre-flash row sitting in the USB tab next to the new one, advertising a
        // port that no longer exists and the firmware version it no longer runs.
        //
        // Routed through the UI marshal like every other AvailableSerialDevices mutation. The
        // message clear is unconditional — both entry points are starting discovery again, so
        // whatever the previous run gave up with is stale either way (issue #290).
        _marshalToUiThread(() =>
        {
            SerialDiscoveryError = null;
            if (clearDiscoveredDevices)
            {
                AvailableSerialDevices.Clear();
                HasNoSerialDevices = true;
            }
        });

        _serialConsecutiveFaults = 0;

        var inner = _createSerialFinder();

        var finder = new ContinuousDeviceFinder(
            inner,
            new ContinuousDiscoveryOptions
            {
                Interval = _serialScanInterval,
                PassTimeout = _serialPassTimeout,

                // Key the live set by port name, which is what AvailableSerialDevices is keyed by
                // (FindSerialDeviceByPortName). Core's default prefers serial number — deliberately,
                // so a device survives COM-port reassignment — but that would leave the bound row
                // advertising the old port after a replug, because a metadata-only change refreshes
                // Core's tracked copy silently and raises no event the dialog could act on. Keying on
                // the port instead makes a replug a loss and a fresh discovery, which is exactly what
                // the tile has to show. Falls back to the serial number so a finder that reports no
                // port name still gets a stable key rather than colliding on the empty string.
                IdentitySelector = static device =>
                    !string.IsNullOrWhiteSpace(device.PortName)
                        ? "port:" + device.PortName.Trim().ToLowerInvariant()
                        : "sn:" + device.SerialNumber,
            });

        // The serial counterpart of the reset in StartWiFiDiscovery, with the same currency guard and
        // for the same reason — see there.
        inner.DiscoveryCompleted += (_, _) =>
        {
            if (ReferenceEquals(finder, _serialFinder)) { _serialConsecutiveFaults = 0; }
        };

        finder.DeviceDiscovered += HandleCoreSerialDeviceDiscovered;
        finder.DeviceLost += HandleCoreSerialDeviceLost;
        finder.ScanError += HandleSerialScanError;
        _serialFinder = finder;
        finder.Start();
    }

    /// <summary>
    /// How many consecutive faulted passes either scan tolerates before the dialog stops believing in
    /// it. A single fault is a bad pass, not a broken finder — the wrapped finder enumerates ports and
    /// sockets on every pass, and one hiccup there used to end discovery for the life of the dialog
    /// because the general <c>catch</c> sat outside the <c>while</c> (issue #290).
    /// <para>
    /// Core scopes a faulted pass correctly on its own — <c>ScanLoopAsync</c> reports it through
    /// <see cref="ContinuousDeviceFinder.ScanError"/> and keeps scanning — so what remains here is only
    /// the give-up, which is a dialog decision rather than a library one: a UI that cannot say "this is
    /// not working" has to animate "Scanning…" over a permanently broken finder for ever.
    /// </para>
    /// </summary>
    private const int MaxConsecutiveDiscoveryFaults = 3;

    /// <summary>
    /// A serial discovery pass faulted. Stops the dialog's scan — and says so where the user is
    /// looking — once <see cref="MaxConsecutiveDiscoveryFaults"/> have gone by with no clean pass
    /// between them (issue #290).
    /// </summary>
    private void HandleSerialScanError(object? sender, ContinuousDiscoveryErrorEventArgs e)
    {
        if (!ReferenceEquals(sender, _serialFinder)) { return; }

        var faults = ++_serialConsecutiveFaults;
        Common.Loggers.AppLogger.Instance.Error(
            e.Exception,
            $"Serial discovery pass failed (fault {faults}/{MaxConsecutiveDiscoveryFaults}).");

        if (faults < MaxConsecutiveDiscoveryFaults) { return; }

        // The give-up has to reach the dialog, not just DAQifiAppLog.log: the animated "Scanning for
        // USB devices…" overlay binds to IsSerialDiscoveryScanning, and a discovery that has stopped
        // for good is indistinguishable from one still looking without this (issue #290).
        _marshalToUiThread(() => SerialDiscoveryError =
            "USB discovery stopped after repeated errors. Close and reopen this " +
            "window to search again.");

        // Fire-and-forget: this runs on Core's scan-loop thread, and StopAsync waits for that very
        // loop to exit, so awaiting it here would deadlock the loop against itself.
        _ = StopSerialDiscoveryAsync();
    }

    /// <summary>The WiFi counterpart of <see cref="HandleSerialScanError"/>.</summary>
    private void HandleWifiScanError(object? sender, ContinuousDiscoveryErrorEventArgs e)
    {
        if (!ReferenceEquals(sender, _wifiFinder)) { return; }

        var faults = ++_wifiConsecutiveFaults;
        Common.Loggers.AppLogger.Instance.Error(
            e.Exception,
            $"WiFi discovery pass failed (fault {faults}/{MaxConsecutiveDiscoveryFaults}).");

        if (faults < MaxConsecutiveDiscoveryFaults) { return; }

        _marshalToUiThread(() => WiFiDiscoveryError =
            "WiFi discovery stopped after repeated errors. Close and reopen this " +
            "window to search again.");

        _ = StopWiFiDiscoveryAsync();
    }

    #endregion

    #region Commands

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectCommand
    public IAsyncRelayCommand ConnectCommand { get; }
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectSerialCommand
    public IAsyncRelayCommand ConnectSerialCommand { get; }
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectManualSerialCommand
    public IAsyncRelayCommand ConnectManualSerialCommand { get; }
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectManualWifiCommand
    public IAsyncRelayCommand ConnectManualWifiCommand { get; }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectAsync
    private async Task ConnectAsync(object? selectedItems)
    {
        var selectedDevices = ToStreamingDevices(selectedItems);
        if (selectedDevices.Count == 0) { return; }

        // Awaited, unlike the fire-and-forget stop this replaced: the WiFi scan holds a UDP socket the
        // connect is about to use, and Core's ordered stop is what makes "stopped" mean "released".
        await StopWiFiDiscoveryAsync();

        foreach (var device in selectedDevices)
        {
            // This path reads no result at all, so it cannot misattribute one — it closes the
            // dialog whatever happens. That is the same missing-feedback gap the USB tab had before
            // issue #207, and closing it needs a WiFi-tab error surface (a bound message, a colour,
            // a rendered baseline), not a result type. Out of scope here, which is about attributing
            // a result to the right device rather than about growing a new one.
            await ConnectionManager.Instance.Connect(device);
        }

        RaiseCloseRequested();
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectSerialAsync
    private async Task ConnectSerialAsync(object? selectedItems)
    {
        var selectedDevices = ToStreamingDevices(selectedItems);
        if (selectedDevices.Count == 0) { return; }

        SerialConnectError = null;

        await StopSerialDiscoveryAsync();

        // Act on each device's OWN result, per device. A discovered device can fail here (e.g. one
        // left streaming over WiFi returns a SCPI error when told to switch to USB), and without
        // this check the dialog closes silently with no feedback at all — the device simply never
        // appears in the device list.
        foreach (var device in selectedDevices)
        {
            var result = await ConnectionManager.Instance.Connect(device);
            if (result.IsConnected) { continue; }

            if (result.WasCancelledByUser)
            {
                // The duplicate-device prompt was declined. Nothing failed, so say nothing — but
                // don't close either, because the user did not ask for this device after all.
                ResumeSerialDiscoveryKeepingDiscoveredDevices();
                return;
            }

            // Named off the result, not off the loop variable: the message and the outcome it
            // describes then cannot come from two different devices, whatever else is in flight.
            SerialConnectError =
                $"Could not connect to '{result.Device.Name}'. " +
                "The device may be in use by another application or not responding.";
            // Resume the discovery this method drained above, so the dialog is not left with a
            // frozen list after a failed attempt, and deliberately WITHOUT clearing the list: the
            // device that just failed is the one the user is most likely to retry, and blanking the
            // list back to "Scanning…" would make them wait for it to be rediscovered first.
            // Upstream does not clear here either.
            ResumeSerialDiscoveryKeepingDiscoveredDevices();
            return;
        }

        RaiseCloseRequested();
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectManualSerialAsync
    private async Task ConnectManualSerialAsync()
    {
        ManualPortError = null;

        if (string.IsNullOrWhiteSpace(ManualPortName)) { return; }

        var portName = ManualPortName.Trim();

        // Port enumeration reads the registry; keep it off the UI thread per the
        // app's async/UI-responsiveness standards (this runs before the first await).
        if (!await Task.Run(() => IsPortAvailable(portName)))
        {
            // Avoid the FileNotFoundException round-trip from SerialPort.Open by
            // pre-checking against the system's enumerated ports. Surface a friendly
            // message in the dialog instead of silently closing.
            ManualPortError =
                $"Port '{portName}' is not available. " +
                "Plug in the device or check Device Manager for the correct port name.";
            Common.Loggers.AppLogger.Instance.Warning(
                $"Manual serial connect rejected: port '{portName}' is not present on the system.");
            return;
        }

        // Drain serial discovery before opening the port — same exclusive-access guarantee the
        // discovered-device path (ConnectSerialAsync) already takes. The continuous SerialDeviceFinder
        // loop opens/probes every DAQiFi-VID/PID COM port each cycle (and a probe on a port that never
        // answers the identify sits there holding the handle), so without this the app races ITSELF for
        // the port and the open fails "in use by another process". This is the common path for a device
        // stranded in transparent mode: it isn't auto-discovered, so the user connects to it by port
        // here while discovery is still hammering it.
        await StopSerialDiscoveryAsync();

        ManualSerialDevice = new SerialStreamingDevice(portName);
        var result = await ConnectionManager.Instance.Connect(ManualSerialDevice);

        // Post-connect check covers failures the pre-flight enumeration cannot catch — most notably
        // "port exists but is held by another process", which SerialStreamingDevice.Connect
        // classifies as a Warning (no Sentry capture). Without this, the dialog would close silently
        // and the user would have no idea the connection failed.
        if (!result.IsConnected)
        {
            if (!result.WasCancelledByUser)
            {
                ManualPortError =
                    $"Could not connect to '{portName}'. " +
                    "The port may be in use by another application or the device is not responding.";
            }

            // Restart discovery so the dialog keeps finding devices after a failed manual attempt.
            // Keeps the discovered list, for the same retry reason as the USB tab's failure path.
            ResumeSerialDiscoveryKeepingDiscoveredDevices();
            return;
        }

        RaiseCloseRequested();
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.IsPortAvailable
    private static bool IsPortAvailable(string portName)
    {
        try
        {
            return SerialPort.GetPortNames()
                .Any(p => string.Equals(p, portName, StringComparison.OrdinalIgnoreCase));
        }
        catch (Exception ex)
        {
            // If port enumeration itself fails, fall back to the connect attempt rather
            // than blocking the user — Connect() will surface its own error path.
            Common.Loggers.AppLogger.Instance.Warning(ex,
                "Failed to enumerate serial ports during manual-connect validation.");
            return true;
        }
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectManualWifiAsync
    private async Task ConnectManualWifiAsync()
    {
        ManualWifiError = null;

        if (string.IsNullOrWhiteSpace(ManualIpAddress)) { return; }

        var endpointInput = ManualIpAddress.Trim();
        IPAddress? ipAddress;
        try
        {
            ipAddress = await ResolveManualWifiEndpointAsync(endpointInput);
        }
        catch (ArgumentException ex)
        {
            ManualWifiError = $"'{endpointInput}' is not a valid IP address or host name.";
            Common.Loggers.AppLogger.Instance.Warning(ex,
                $"Manual WiFi connection requires a valid IP address or host name. " +
                $"Received '{ManualIpAddress}'");
            return;
        }
        catch (SocketException ex)
        {
            ManualWifiError = $"Could not resolve '{endpointInput}'. Check the address and try again.";
            Common.Loggers.AppLogger.Instance.Warning(ex,
                $"Failed to resolve manual WiFi endpoint '{ManualIpAddress}'");
            return;
        }
        catch (Exception ex)
        {
            Common.Loggers.AppLogger.Instance.Error(
                ex,
                $"Unexpected error while resolving manual WiFi endpoint '{ManualIpAddress}'.");
            throw;
        }

        if (ipAddress == null)
        {
            ManualWifiError = $"Could not resolve '{endpointInput}'. Check the address and try again.";
            Common.Loggers.AppLogger.Instance.Warning(
                $"Manual WiFi endpoint '{ManualIpAddress}' did not resolve to an IP address.");
            return;
        }

        // Connect directly with the resolved endpoint instead of fabricating a discovery-shaped
        // IDeviceInfo — the device wrapper drives the connection through Core's DaqifiDeviceFactory
        // (issue #620). The hardcoded 9760 data port is tracked separately in issue #615.
        const int MANUAL_WIFI_DATA_PORT = 9760;
        var device = new DaqifiStreamingDevice(ipAddress, MANUAL_WIFI_DATA_PORT, "Manual IP Device");
        var result = await ConnectionManager.Instance.Connect(device);

        // Post-connect check mirrors the manual-serial path: an unreachable device (connect
        // timeout — issue #517) must keep the dialog open with an inline message instead of
        // closing silently.
        if (!result.IsConnected)
        {
            if (!result.WasCancelledByUser)
            {
                ManualWifiError =
                    $"Could not connect to '{endpointInput}'. " +
                    "Verify the device is powered on and reachable on this network.";
            }

            return;
        }

        RaiseCloseRequested();
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ToStreamingDevices
    private static List<IStreamingDevice> ToStreamingDevices(object? selectedItems)
    {
        if (selectedItems is not IEnumerable enumerable) { return []; }
        return enumerable.Cast<IStreamingDevice>().ToList();
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.RaiseCloseRequested
    private void RaiseCloseRequested()
    {
        CloseRequested?.Invoke(this, EventArgs.Empty);
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ResolveManualWifiEndpointAsync
    private static async Task<IPAddress?> ResolveManualWifiEndpointAsync(string endpointInput)
    {
        if (IPAddress.TryParse(endpointInput, out var parsedIpAddress))
        {
            return parsedIpAddress;
        }

        var resolvedAddresses = await Dns.GetHostAddressesAsync(endpointInput);
        return resolvedAddresses.FirstOrDefault(
            address => address.AddressFamily == AddressFamily.InterNetwork)
            ?? resolvedAddresses.FirstOrDefault();
    }

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.ConnectHid
    private async Task ConnectHid(object selectedItems)
    {
        if (selectedItems is not IEnumerable enumerable) { return; }

        var bootloader = enumerable.Cast<HeldBootloader>().FirstOrDefault();
        if (bootloader == null) { return; }

        await RunWithHidFlashQuiescedAsync(() =>
        {
            var firmwareDialogViewModel = new FirmwareDialogViewModel(bootloader.DisplayName, bootloader.DevicePath);
            return _dialogService.ShowDialogAsync<FirmwareDialog>(this, firmwareDialogViewModel);
        });
    }

    /// <summary>
    /// Runs the (modal) HID firmware dialog with WiFi + serial discovery quiesced for the whole window,
    /// then restores discovery.
    /// </summary>
    /// <param name="showFirmwareDialogAsync">
    /// Shows the modal firmware dialog; the returned task completes once it has closed. Upstream takes a
    /// plain <c>Action</c> because WPF's <c>ShowDialog</c> blocks — Avalonia's dialogs are async-only, so
    /// the same "run this while quiesced" contract needs a <see cref="Func{Task}"/> here.
    /// </param>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.RunWithHidFlashQuiescedAsync
    private async Task RunWithHidFlashQuiescedAsync(Func<Task> showFirmwareDialogAsync)
    {
        // Pause WiFi + serial discovery while the firmware dialog is open: their per-cycle bus probing
        // (serial opens/probes every COM port; WiFi UDP-broadcasts) can starve the bootloader's HID I/O
        // mid-flash. HID discovery and the per-device holds belong to the app-global watcher — it pauses
        // HID discovery and releases the target's hold itself when the flash starts
        // (FirmwareDialogViewModel → BootloaderWatcher.PrepareFlashAsync), while every OTHER held
        // bootloader stays wedge-proof. Awaiting the drains matters: cancel/dispose does NOT abort an
        // in-flight DiscoverAsync cycle, so a still-running probe could otherwise hold a handle when the
        // flasher fires.
        //
        // The flag goes up BEFORE the drains: a coordinator auto-update of a different device can finish
        // while we are awaiting them, and its FirmwareUpdateInProgressChanged handler would otherwise
        // restart the very discovery we are tearing down (issue #777).
        _hidFirmwareDialogOpen = true;
        try
        {
            await StopWiFiDiscoveryAsync();
            await StopSerialDiscoveryAsync();

            await showFirmwareDialogAsync();
        }
        finally
        {
            // Resume discovery once the flash dialog closes so the device list stays live. The watcher
            // keeps holding the bootloader (or drops it if the flash succeeded) on its own. If an
            // auto-update or a still-unwinding bootloader write is holding the bus, this restart is
            // refused and that operation's own release path retries it.
            _hidFirmwareDialogOpen = false;
            RestartDiscoveryAfterFirmwarePause();
        }
    }
    #endregion

    #region Core Device Discovery Event Handlers

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.HandleCoreWifiDeviceDiscovered
    internal void HandleCoreWifiDeviceDiscovered(object? sender, DeviceDiscoveredEventArgs e)
    {
        try
        {
            Common.Loggers.AppLogger.Instance.AddBreadcrumb("discovery", $"WiFi device found: {e.DeviceInfo.Name}");
            var wifiDevice = new DaqifiStreamingDevice(e.DeviceInfo);
            HandleWifiDeviceFound(sender, wifiDevice);
        }
        catch (Exception ex)
        {
            Common.Loggers.AppLogger.Instance.Error(ex, "Error handling WiFi device discovery");
        }
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.HandleCoreSerialDeviceDiscovered
    private void HandleCoreSerialDeviceDiscovered(object? sender, DeviceDiscoveredEventArgs e)
    {
        try
        {
            Common.Loggers.AppLogger.Instance.AddBreadcrumb("discovery", $"Serial device found: {e.DeviceInfo.Name}");
            // sender is the finder that raised this (Core raises with `this`), and it is carried
            // through so the mutation can check it is still the current one — see below.
            AddSerialDeviceFromDiscovery(sender, e.DeviceInfo);
        }
        catch (Exception ex)
        {
            Common.Loggers.AppLogger.Instance.Error(ex, "Error handling Serial device discovery");
        }
    }

    /// <summary>
    /// A serial device has been absent for <see cref="ContinuousDiscoveryOptions.MissThreshold"/>
    /// consecutive passes, so drop its tile.
    /// </summary>
    /// <remarks>
    /// New behaviour, and the reason the live set is keyed by port name: the hand-rolled loop never
    /// removed anything, so a board unplugged with the dialog open kept its tile until the dialog was
    /// closed and reopened, and pressing Connect on it failed on a port that was no longer there.
    /// Core's busy-port rescue (issue #532) keeps a device the app itself holds from being reported
    /// lost, so this does not fire for the board the user just connected to.
    /// </remarks>
    private void HandleCoreSerialDeviceLost(object? sender, DeviceLostEventArgs e)
    {
        try
        {
            var portName = e.DeviceInfo.PortName?.Trim();
            if (string.IsNullOrWhiteSpace(portName)) { return; }

            _marshalToUiThread(() =>
            {
                if (!ReferenceEquals(sender, _serialFinder)) { return; }

                var listed = FindSerialDeviceByPortName(portName);
                if (listed == null) { return; }

                AvailableSerialDevices.Remove(listed);
                HasNoSerialDevices = AvailableSerialDevices.Count == 0;
                Common.Loggers.AppLogger.Instance.Information(
                    $"Removed DAQiFi device on {portName}: no longer answering discovery.");
            });
        }
        catch (Exception ex)
        {
            Common.Loggers.AppLogger.Instance.Error(ex, "Error handling Serial device loss");
        }
    }

    /// <summary>The WiFi counterpart of <see cref="HandleCoreSerialDeviceLost"/>, keyed by MAC.</summary>
    private void HandleCoreWifiDeviceLost(object? sender, DeviceLostEventArgs e)
    {
        try
        {
            var macAddress = e.DeviceInfo.MacAddress;
            if (string.IsNullOrWhiteSpace(macAddress)) { return; }

            _marshalToUiThread(() =>
            {
                if (!ReferenceEquals(sender, _wifiFinder)) { return; }

                var listed = AvailableWiFiDevices.FirstOrDefault(d => d.MacAddress == macAddress);
                if (listed == null) { return; }

                AvailableWiFiDevices.Remove(listed);
                HasNoWiFiDevices = AvailableWiFiDevices.Count == 0;
            });
        }
        catch (Exception ex)
        {
            Common.Loggers.AppLogger.Instance.Error(ex, "Error handling WiFi device loss");
        }
    }

    /// <param name="finder">
    /// The finder that raised the discovery. Used to reject a retired finder's late callback — see
    /// the guard inside the marshalled action.
    /// </param>
    /// <param name="deviceInfo">What the finder found.</param>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.AddSerialDeviceFromDiscovery
    private void AddSerialDeviceFromDiscovery(object? finder, CoreDeviceInfo deviceInfo)
    {
        var portName = deviceInfo.PortName?.Trim();
        if (string.IsNullOrWhiteSpace(portName))
        {
            return;
        }

        _marshalToUiThread(() =>
        {
            // Only the CURRENT finder may touch the list, and the check has to happen here rather
            // than before the marshal. Unsubscribing DeviceDiscovered does not revoke a raise
            // already in flight, and the action this queues can land behind the very
            // StartSerialFinder call that retired the finder — so a late callback would otherwise
            // put a pre-flash port straight back into the list the clear had just emptied, or
            // overwrite the new session's metadata with the old session's. Core's pass timeout makes
            // this concrete: a pass abandoned on a wedged port can still identify a device long
            // afterwards. A rejected discovery costs at most one pass — the current finder reports the
            // device again if it is really there.
            //
            // Also rejects everything once the dialog has stopped discovery, because
            // StopSerialDiscoveryAsync nulls the field before it awaits the ordered stop.
            if (finder == null || !ReferenceEquals(finder, _serialFinder)) { return; }

            var existing = FindSerialDeviceByPortName(portName);
            if (existing == null)
            {
                var serialDevice = new SerialStreamingDevice(
                    portName,
                    deviceInfo.Name,
                    deviceInfo.SerialNumber,
                    deviceInfo.FirmwareVersion)
                {
                    LocationKey = deviceInfo.LocationKey
                };
                AvailableSerialDevices.Add(serialDevice);
                if (HasNoSerialDevices) { HasNoSerialDevices = false; }
                Common.Loggers.AppLogger.Instance.Information(
                    $"Added DAQiFi device on {portName}: {serialDevice.Name} (S/N: {serialDevice.DeviceSerialNo})");
                return;
            }

            UpdateSerialDeviceMetadata(existing, portName, deviceInfo);
        });
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.FindSerialDeviceByPortName
    private SerialStreamingDevice? FindSerialDeviceByPortName(string portName)
    {
        return AvailableSerialDevices.FirstOrDefault(d =>
            d.PortName.Equals(portName, StringComparison.OrdinalIgnoreCase));
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.UpdateSerialDeviceMetadata
    private static void UpdateSerialDeviceMetadata(
        SerialStreamingDevice serialDevice,
        string portName,
        CoreDeviceInfo deviceInfo)
    {
        serialDevice.Name = !string.IsNullOrWhiteSpace(deviceInfo.Name)
            ? deviceInfo.Name
            : portName;
        serialDevice.DeviceSerialNo = deviceInfo.SerialNumber;
        serialDevice.DeviceVersion = deviceInfo.FirmwareVersion;

        // Only overwrite with a resolved value: a refresh pass that couldn't resolve a location
        // (deviceInfo.LocationKey null) must not erase a previously-captured one, or an auto-update
        // triggered afterward would lose its firmware-targeting key.
        if (!string.IsNullOrWhiteSpace(deviceInfo.LocationKey))
        {
            serialDevice.LocationKey = deviceInfo.LocationKey;
        }
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.InvokeOnUiThread
    private static void InvokeOnUiThread(Action action)
    {
        if (Dispatcher.UIThread.CheckAccess())
        {
            action();
            return;
        }

        Dispatcher.UIThread.Invoke(action);
    }

    #endregion

    #region Desktop Device Event Handlers

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.HandleWifiDeviceFound
    // `object?`, not the upstream `object`: this is not an event handler and has no target
    // delegate — its one caller is HandleCoreWifiDeviceDiscovered, whose own `sender` comes from
    // Core's event and is declared nullable there. Promising more than that caller can supply was
    // CS8604 at the call site. The parameter is never read here, so widening it cannot change
    // behaviour, and NRT annotations are erased at runtime — the emitted signature is unchanged.
    private void HandleWifiDeviceFound(object? sender, IDevice device)
    {
        if (device is not DaqifiStreamingDevice wifiDevice)
        {
            return;
        }

        _marshalToUiThread(() =>
        {
            // Only the CURRENT scan may touch the list — the same guard, for the same reason, as
            // AddSerialDeviceFromDiscovery's. Previously absent here (the serial one's comment called
            // this out as a known hole, partly masked by the MAC dedup below); it can be closed now
            // because `sender` is the ContinuousDeviceFinder this dialog holds rather than a finder it
            // rebuilt mid-run, so "is this still the current one" is a reference comparison.
            if (!ReferenceEquals(sender, _wifiFinder)) { return; }

            // Dedup by MAC. Core's ContinuousDeviceFinder keys its live set by MAC too, so it raises
            // this once per device rather than once per pass; the guard stays because the bound list
            // outlives a single scan — StartWiFiDiscovery's clear fires on scan recreate, not per pass,
            // so a device listed by the previous scan is still here when the next one finds it again.
            // (issue #621)
            if (AvailableWiFiDevices.Any(d => d.MacAddress == wifiDevice.MacAddress)) return;
            AvailableWiFiDevices.Add(wifiDevice);
            if (HasNoWiFiDevices) { HasNoWiFiDevices = false; }
        });
    }

    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.Close
    public void Close()
    {
        // Guards against concurrent/double dispose when the window closes while
        // a connect command is still in flight (either path may call this).
        if (_closed) { return; }
        _closed = true;

        // Fire-and-forget: stop both scans and release their ports without blocking the window close.
        _ = StopWiFiDiscoveryAsync();
        _ = StopSerialDiscoveryAsync();

        ConnectionManager.Instance.FirmwareUpdateInProgressChanged -= OnFirmwareUpdateInProgressChanged;

        // HID bootloader holds are owned by the app-global watcher and intentionally persist after the
        // dialog closes (so a sitting bootloader stays wedge-proof). Only unsubscribe this dialog from
        // the watcher's list.
        if (_watcher != null)
        {
            ((System.Collections.Specialized.INotifyCollectionChanged)_watcher.Bootloaders).CollectionChanged
                -= OnHidDevicesChanged;
            _watcher.FlashInProgressChanged -= OnBootloaderFlashInProgressChanged;
        }
    }

    /// <summary>
    /// Stops serial discovery and does not return until the scan loop has actually exited and the
    /// finder — and with it every port it had open — has been released.
    /// </summary>
    /// <remarks>
    /// The port-release contract is what the connect paths depend on: <c>ConnectSerialAsync</c> awaits
    /// this before opening the port itself, and a probe still holding it would surface to the user as a
    /// false "port in use". The hand-rolled loop had to arrange that by hand — cancel, then drain the
    /// in-flight sweep, bounded, before letting cancellation propagate — because cancelling its
    /// <c>Task.WhenAny</c> raced the sweep that still held the port. <see cref="ContinuousDeviceFinder.StopAsync"/>
    /// owns that ordering now: it cancels the loop and awaits its exit, and <c>Dispose</c> then disposes
    /// the wrapped finder. Bounded anyway, because a pass abandoned on a wedged port unwinds on its own
    /// schedule and the dialog must not hang waiting for it.
    /// </remarks>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.StopSerialDiscoveryAsync
    private Task StopSerialDiscoveryAsync()
    {
        // Atomic take: whoever wins gets the finder, everyone else gets null and returns. A stop can
        // be started from Core's scan-loop thread (the third-fault give-up) at the same moment the UI
        // thread starts one from Close, a connect, or a firmware pause — and a plain read-then-null
        // would hand the same instance to both, so both would stop and dispose it.
        var finder = Interlocked.Exchange(ref _serialFinder, null);
        if (finder == null) { return Task.CompletedTask; }

        finder.DeviceDiscovered -= HandleCoreSerialDeviceDiscovered;
        finder.DeviceLost -= HandleCoreSerialDeviceLost;
        finder.ScanError -= HandleSerialScanError;
        return StopDiscoveryAsync(finder, _serialPassTimeout, "serial");
    }

    /// <summary>
    /// The WiFi counterpart of <see cref="StopSerialDiscoveryAsync"/>. Used before a bootloader flash
    /// so a running UDP discovery cycle isn't still live when the flash begins.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.StopWiFiDiscoveryAsync
    private Task StopWiFiDiscoveryAsync()
    {
        // Atomic take — see StopSerialDiscoveryAsync.
        var finder = Interlocked.Exchange(ref _wifiFinder, null);
        if (finder == null) { return Task.CompletedTask; }

        finder.DeviceDiscovered -= HandleCoreWifiDeviceDiscovered;
        finder.DeviceLost -= HandleCoreWifiDeviceLost;
        finder.ScanError -= HandleWifiScanError;
        return StopDiscoveryAsync(finder, _wifiPassTimeout, "WiFi");
    }

    /// <summary>
    /// The shared stop body: await the ordered stop, bounded, then dispose either way.
    /// </summary>
    /// <remarks>
    /// Disposing is what releases the wrapped finder's ports and sockets —
    /// <see cref="ContinuousDeviceFinder"/> owns the finder it was given
    /// (<see cref="ContinuousDiscoveryOptions.LeaveInnerFinderOpen"/> is left false), so it disposes it
    /// — and it must happen even when the bounded wait gave up, which is why it is in a <c>finally</c>.
    /// </remarks>
    private static async Task StopDiscoveryAsync(
        ContinuousDeviceFinder finder,
        TimeSpan passTimeout,
        string transport)
    {
        try
        {
            // The loop can be mid-pass, so allow the pass its full budget plus slack to observe
            // cancellation and unwind — the same bound HidBootloaderDiscovery uses, scaled to this
            // transport's pass timeout.
            await finder.StopAsync().WaitAsync(passTimeout + TimeSpan.FromSeconds(2));
        }
        catch (TimeoutException)
        {
            Common.Loggers.AppLogger.Instance.Warning(
                $"{transport} discovery did not stop within timeout");
        }
        catch (OperationCanceledException)
        {
            // Expected on cancellation.
        }
        catch (ObjectDisposedException)
        {
            // Expected during shutdown.
        }
        catch (Exception ex)
        {
            Common.Loggers.AppLogger.Instance.Error(ex, $"Unexpected error while stopping {transport} discovery");
        }
        finally
        {
            finder.Dispose();
        }
    }

    /// <summary>
    /// Handles duplicate device detection by showing a dialog to the user
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ConnectionDialogViewModel.HandleDuplicateDevice
    // Async divergence: Avalonia ShowDialog is async-only; ConnectionManager awaits the
    // Task-returning handler (see DuplicateDeviceHandler dialect note there).
    private async Task<DuplicateDeviceAction> HandleDuplicateDevice(DuplicateDeviceCheckResult duplicateResult)
    {
        try
        {
            // Create dialog manually since we need access to the Result property
            var duplicateDialogViewModel = new DuplicateDeviceDialogViewModel(
                duplicateResult.ExistingDevice,
                duplicateResult.NewDevice,
                duplicateResult.ExistingDeviceInterface,
                duplicateResult.NewDeviceInterface);

            var dialog = new DuplicateDeviceDialog();
            dialog.DataContext = duplicateDialogViewModel;
            
            // Find the owner window — Avalonia dialogs require an owner; fall back to the
            // main window when this VM isn't a window's DataContext.
            if (Application.Current?.ApplicationLifetime is not IClassicDesktopStyleApplicationLifetime desktop)
            {
                return DuplicateDeviceAction.Cancel;
            }

            var ownerWindow = desktop.Windows.FirstOrDefault(w => w.DataContext == this)
                ?? desktop.MainWindow;
            if (ownerWindow == null)
            {
                return DuplicateDeviceAction.Cancel;
            }

            dialog.WindowStartupLocation = WindowStartupLocation.CenterOwner;

            var dialogResult = await dialog.ShowDialog<bool?>(ownerWindow);
            
            if (dialogResult == true)
            {
                return dialog.Result switch
                {
                    DuplicateDeviceDialog.DuplicateDeviceDialogResult.KeepExisting => DuplicateDeviceAction.KeepExisting,
                    DuplicateDeviceDialog.DuplicateDeviceDialogResult.SwitchToNew => DuplicateDeviceAction.SwitchToNew,
                    _ => DuplicateDeviceAction.Cancel
                };
            }

            return DuplicateDeviceAction.Cancel;
        }
        catch (Exception ex)
        {
            // Log error and default to cancel - this should rarely happen
            Daqifi.Desktop.Common.Loggers.AppLogger.Instance.Error(ex, "Failed to show duplicate device dialog");
            return DuplicateDeviceAction.Cancel;
        }
    }
    #endregion
}
